using System;using System.IO;using System.Diagnostics;using System.Security.Cryptography;using BIMaestro.Home;
class PreviewTest{
 static string Hash(string p){using(var f=File.OpenRead(p))using(var sha=SHA256.Create()){var b=new byte[Math.Min(65536,f.Length)];int n=f.Read(b,0,b.Length);return Convert.ToBase64String(sha.ComputeHash(b,0,n));}}
 static int Main(string[] args){int success=0,failed=0; foreach(var p in args){var before=new FileInfo(p);long size=before.Length;DateTime stamp=before.LastWriteTimeUtc;string hash=Hash(p);var w=Stopwatch.StartNew();var b=HomeEmbeddedPreview.TryRead(p);w.Stop();var after=new FileInfo(p);if(size!=after.Length||stamp!=after.LastWriteTimeUtc||hash!=Hash(p))throw new Exception("Source changed");if(b!=null)success++;else failed++;Console.WriteLine("{0}\t{1}\t{2}\t{3}",Path.GetExtension(p),b==null?0:b.Length,w.Elapsed.TotalMilliseconds.ToString("F3",System.Globalization.CultureInfo.InvariantCulture),Path.GetFileName(p));}
 if(HomeEmbeddedPreview.TryRead(null)!=null||HomeEmbeddedPreview.TryRead(@"\\server\share\model.rvt")!=null||HomeEmbeddedPreview.TryRead("relative.rvt")!=null)throw new Exception("Path guards");
 string folder=Path.Combine(Environment.CurrentDirectory,"tmp/home-tests/catalog/invalid-previews");Directory.CreateDirectory(folder);
 foreach(int kind in new[]{0,1,2}){byte[] bytes=new byte[kind==0?2:1536];if(kind>0){byte[] sig={0xd0,0xcf,0x11,0xe0,0xa1,0xb1,0x1a,0xe1};Buffer.BlockCopy(sig,0,bytes,0,8);Action<int,ushort> u16=(at,v)=>Buffer.BlockCopy(BitConverter.GetBytes(v),0,bytes,at,2);Action<int,uint> u32=(at,v)=>Buffer.BlockCopy(BitConverter.GetBytes(v),0,bytes,at,4);u16(26,3);u16(28,0xfffe);u16(30,9);u16(32,6);u32(56,4096);u32(44,kind==1?uint.MaxValue:1);u32(48,1);for(int i=0;i<109;i++)u32(76+i*4,uint.MaxValue);u32(76,0);for(int i=0;i<128;i++)u32(512+i*4,uint.MaxValue);u32(512+4,1);}
 string p=Path.Combine(folder,"invalid-"+kind+".rvt");File.WriteAllBytes(p,bytes);if(HomeEmbeddedPreview.TryRead(p)!=null)throw new Exception("Malformed CFB accepted");}
 Console.WriteLine("SUCCESS "+success+" ABSENT "+failed+" SOURCE PREFIX HASH/SIZE/TIME UNCHANGED "+args.Length+" INVALID GUARDS 6");return 0;}}
